{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill would change one part of Tennessee law on interscholastic athletics, Tennessee Code Annotated Section 49-2-136(b). It would delete subdivision (2) of that subsection and replace it with a new reporting rule. Under the new rule, if the Senate education committee or the House committee with jurisdiction over education asks for it, the department must send that committee a report. The report must document whether each local education agency (LEA) and each public charter school is complying with Section 49-2-136.",
      "rationale": "The summary identifies the provision replaced, both authorized requesting committees, the department's mandatory reporting duty, the recipient, and the compliance reporting scope covering each LEA and public charter school."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would take effect as soon as it becomes law.",
      "rationale": "The summary accurately conveys that the act takes effect upon becoming law."
    }
  ]
}
